// go/ch30/tutorial_outline.go
// 解いた AHC 問題のゆっくり風チュートリアル骨子を Markdown で生成（第30章）
// python/ch30/tutorial_outline.py と同じ出力（末尾の generated by 行だけ異なる）
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// 解説骨子の雛形。”' はバッククォート（`）に置換される
const outlineTemplate = `# 【ゆっくり解説骨子】{{PID}} {{TITLE}}

> 対象: {{BAND}} / 自分の到達スコア: {{SCORE}} / 方針: '''{{STYLE}}''' / 所要: 約{{HOURS}}時間

## はじめに

**霊夢**: {{PID}}って、何をする問題なの？

**魔理沙**: 一言で言うと「{{TITLE}}」だぜ。まずは制約とスコアの意味を押さえるんだ。

## この解説で扱うこと

{{KEY_IDEAS}}

## 落とし穴メモ

{{PITFALLS}}

---

{{SECTIONS}}
## ハンズオン（読者向け）

{{HANDSON}}

'''''''''bash
{{COMMANDS}}
'''''''''

## 章末まとめ（テンプレ）

> - 問題の言い換えができた
> - 貪欲/近傍のどこで効いたか言語化した
> - 次に試す改善を 1 つ書いた

## 参考リンク

{{REFS}}

---
*generated by go/ch30/tutorial_outline.go*
`

var defaultHandson = []string{
	"問題文の入出力の形を、サンプルで確かめる",
	"自分の解法を動かし、スコアを出す",
	"パラメータを 1 つだけ変えて差分を見る",
	"タイマー付きでベストスコアを stderr に残す",
}

type meta map[string]any

// key がなければ def を返す。数値は JSON の表記のまま文字列にする
func (m meta) str(key, def string) string {
	v, ok := m[key]
	if !ok || v == nil {
		return def
	}
	return fmt.Sprint(v)
}

func (m meta) list(key string) []string {
	raw, _ := m[key].([]any)
	out := make([]string, 0, len(raw))
	for _, x := range raw {
		out = append(out, fmt.Sprint(x))
	}
	return out
}

func loadMeta(path string) (meta, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	dec := json.NewDecoder(f)
	dec.UseNumber() // 485000 のような数が 4.85e+05 にならないように
	var m meta
	if err := dec.Decode(&m); err != nil {
		return nil, err
	}
	return m, nil
}

func bulletLines(items []string) string {
	lines := make([]string, len(items))
	for i, x := range items {
		lines[i] = "- " + x
	}
	return strings.Join(lines, "\n")
}

func generateOutline(m meta) string {
	pid := m.str("problem_id", "AHC???")
	title := m.str("title", "（タイトル未設定）")
	band := m.str("rating_band", m.str("difficulty", "?"))

	var sectionBlocks []string
	for i, sec := range m.list("sections") {
		sectionBlocks = append(sectionBlocks, fmt.Sprintf(
			"### %d. %s\n\n**霊夢**: （ここに読者の疑問）\n\n**魔理沙**: （%sの解説を書く）\n", i+1, sec, sec))
	}

	refsBlock := "- （公式・自分のコードへのリンク）"
	if refs := m.list("references"); len(refs) > 0 {
		refsBlock = bulletLines(refs)
	}
	handson := defaultHandson
	if _, ok := m["handson"]; ok {
		handson = m.list("handson")
	}
	handsonLines := make([]string, len(handson))
	for i, step := range handson {
		handsonLines[i] = fmt.Sprintf("%d. %s", i+1, step)
	}
	commandsBlock := "# （読者が打つコマンドを書く）"
	if cmds := m.list("commands"); len(cmds) > 0 {
		commandsBlock = strings.Join(cmds, "\n")
	}

	return strings.NewReplacer(
		"{{PID}}", pid,
		"{{TITLE}}", title,
		"{{BAND}}", band,
		"{{SCORE}}", m.str("solved_score", "?"),
		"{{STYLE}}", m.str("solver_style", "?"),
		"{{HOURS}}", m.str("time_spent_hours", "?"),
		"{{KEY_IDEAS}}", bulletLines(m.list("key_ideas")),
		"{{PITFALLS}}", bulletLines(m.list("pitfalls")),
		"{{SECTIONS}}", strings.Join(sectionBlocks, "\n"),
		"{{REFS}}", refsBlock,
		"{{HANDSON}}", strings.Join(handsonLines, "\n"),
		"{{COMMANDS}}", commandsBlock,
		"'''", "`", // Go の生文字列にはバッククォートを書けないので置換する
	).Replace(outlineTemplate)
}

// checkCommands は骨子に載せるコマンドを、リポジトリのルートで実際に動かす（公開前チェック）。
func checkCommands(cmds []string) bool {
	ok := true
	for _, cmd := range cmds {
		status := "OK"
		if err := exec.Command("bash", "-c", cmd).Run(); err != nil {
			status = fmt.Sprintf("NG (%v)", err)
			ok = false
		}
		fmt.Fprintf(os.Stderr, "check %s: %s\n", status, cmd)
	}
	return ok
}

func main() {
	check := flag.Bool("check", false, "commands を実際に動かして確かめる（リポジトリのルートで実行）")
	flag.Parse()
	path := filepath.Join("data", "ch30", "ahc001_outline.json")
	if flag.NArg() > 0 {
		path = flag.Arg(0)
	}
	m, err := loadMeta(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if *check {
		if !checkCommands(m.list("commands")) {
			os.Exit(1)
		}
		return
	}
	fmt.Println(generateOutline(m))
	fmt.Fprintf(os.Stderr, "outline for %s written to stdout\n", m.str("problem_id", "?"))
}
